import hashlib
import math

class BloomFilter:
    """A Bloom Filter implementation using a simple bit array and custom hash functions.

    This design uses a bit array to represent the set of items and multiple hash functions 
    to determine the presence of an item. The size of the bit array and the number of hash
    functions are calculated based on the expected items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_size()
        self.hash_count = self._calculate_hash_count()
        self.bit_array = [0] * self.size

    def _calculate_size(self) -> int:
        """Calculate the size of the bit array."""
        numerator = self.expected_items * math.log(self.false_positive_rate)
        denominator = math.log(1 / (math.pow(2, math.log(2))))
        return math.ceil(-numerator / denominator)

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Hash the item with a given seed to produce an index in the bit array."""
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

