class BloomFilter:
    """
    A Bloom Filter implementation using a bit array and multiple hash functions 
    to efficiently determine set membership with a specified false positive rate.
    The optimal size of the bit array and number of hash functions are calculated
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array (m) and number of hash functions (k)
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return max(1, int(-n * math.log(p) / (math.log(2) ** 2)))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate a list of hash values for the item."""
        hashes = []
        for i in range(self.hash_count):
            # Create a unique hash for each function using the item and an index
            hash_value = int(hashlib.sha256(f"{item}{i}".encode()).hexdigest(), 16)
            hashes.append(hash_value % self.size)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

