        # Calculate the size of the bit array (m)
        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.bit_array = [False] * self.size

        # Calculate the number of hash functions (k)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate optimal bit array size using the formula m = - (n * ln(p)) / (ln(2)^2)."""
        return max(1, int(- (n * math.log(p)) / (math.log(2) ** 2)))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions using k = (m / n) * ln(2)."""
        return max(1, int((m / n) * math.log(2)))

    def _get_hashes(self, item: str) -> list:
        """Generate k hash values for the item."""
        hash_values = []
        for i in range(self.hash_count):
            hash_object = hashlib.md5((item + str(i)).encode()).hexdigest()
            hash_value = int(hash_object, 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for hash_value in self._get_hashes(item):
            self.bit_array[hash_value] = True

